style.css:
@-moz-document domain("discord.com") {
/* ===== FORCE STRAWBERRY/PLUM GLOBAL VARIABLES ===== */
  html, body, [id^="app-mount"], div[data-theme] {
    /* Fondos Pastel */
    --background-primary: #ffe6f0 !important;      /* Chat Principal: Lighter Pink */
    --background-secondary: #ffd6eb !important;    /* Sidebars: Deeper Pink */
    --background-secondary-alt: #ffd6eb !important;/* Sub-Paneles */
    --background-tertiary: #ffb3d9 !important;     /* Barra de Servidores Izquierda */
    --background-floating: #ffe0f0 !important;     /* Menús desplegables */
    --background-accent: #ff99cc !important;       /* Acentos de interfaz */
    --channeltextarea-background: #ffe6f0 !important; /* Caja para escribir texto */

    /* ===== RE-ENGINEERED VARIABLE OVERRIDES ===== */
    --background-mentioned: rgba(166, 0, 55, 0.22) !important;       
    --background-mentioned-hover: rgba(166, 0, 55, 0.32) !important; 
    --status-danger: #4d001a !important;            
    --badge-notification-background: #4d001a !important; 

    /* Texto de Alta Visibilidad (Paleta Ciruela) */
    --text-normal: #4d004d !important;         
    --text-muted: #800060 !important;          
    --header-primary: #66004d !important;      
    --header-secondary: #993366 !important;
    --interactive-normal: #800060 !important;  
    --interactive-hover: #66004d !important;   
    --interactive-active: #4d004d !important;  
    --interactive-muted: #b36699 !important;
    
    /* Indicador de Canales / Hover */
    --background-modifier-selected: #ff99cc !important;
    --background-modifier-hover: rgba(255, 153, 204, 0.4) !important;
  }

  /* ===== THE ANTI-CLASS STRIPPER ===== */
  div[id="app-mount"] > div,
  div[class*="appAsidePanelWrapper_"] div[class*="wrapper_"],
  section {
    background-color: transparent !important;
  }

  /* Baseline backdrop style */
  body, 
  div[id="app-mount"] {
    background-color: #ffe6f0 !important;
  }

  /* ===== STRICT SEGREGATION OF THE LAYOUT PANELS ===== */
  
  /* 1. Leftmost Server Column */
  nav {
    background-color: #ffb3d9 !important;
  }
  
  /* 2. Direct Messages Sidebar (Forced to Deeper Pink: #ffd6eb) */
  /* Targets all nested layers from image_ce02a0.png to destroy that stubborn white mask */
  div[class*="sidebar_"],
  nav[class*="privateChannels_"],
  [id="private-channels-list"],
  ul[class*="privateChannelsList_"],
  [id="private-channels-list"] [class*="scroller_"],
  nav[class*="privateChannels_"] [class*="scroller_"] {
    background-color: #ffd6eb !important;
    background: #ffd6eb !important;
  }

  /* 3. The Actual Main Chat Feed Area (Forced to Lighter Pink: #ffe6f0) */
  main,
  main[class*="chatContent_"],
  div[class*="chat_"] {
    background-color: #ffe6f0 !important;
    background: #ffe6f0 !important;
  }

  /* 4. Right-hand Active Members Sidebar Panel (Forced to Deeper Pink: #ffd6eb) */
  aside,
  aside[class*="membersWrap_"],
  div[class*="members_"],
  ul[class*="members_"],
  aside[class*="membersWrap_"] [class*="scroller_"] {
    background-color: #ffd6eb !important;
    background: #ffd6eb !important;
  }

  /* ===== CHAT INPUT CONTAINER BOX ===== */
  main form,
  div[class*="channelTextArea_"] {
    background: transparent !important;
    border: none !important;
  }

  div[class*="scrollableContainer_"] {
    background-color: #ffd6eb !important;
    border: 1px solid #ff99cc !important;
    border-radius: 12px !important;
  }

  div[class*="scrollableContainer_"] div {
    border: none !important;
    background-color: transparent !important;
  }

  /* ===== GENERAL THEME MESSAGE BUBBLES ===== */
  main li div[role="document"]:not([class*="mentioned_"]),
  main [class*="message_"]:not([class*="mentioned_"]),
  div[class*="message_"]:not([class*="mentioned_"]) {
    background: #fff0f6 !important; 
    border-radius: 12px !important;
    margin-left: 6px !important;
    margin-right: 6px !important;
    transition: background 0.15s ease;
  }
  main li div[role="document"]:not([class*="mentioned_"]):hover,
  main [class*="message_"]:not([class*="mentioned_"]):hover,
  div[class*="message_"]:not([class*="mentioned_"]):hover {
    background: #ffd6eb !important;
  }

  /* ===== IMMUTABLE TRANSLUCENT CRIMSON MENTION CONTAINER ===== */
  main div[class*="message_"][class*="mentioned_"],
  div[class*="message_"][class*="mentioned_"],
  div[class*="mentioned_"] {
    background-color: rgba(166, 0, 55, 0.22) !important; 
    background: rgba(166, 0, 55, 0.22) !important;
    border-radius: 12px !important;
    margin-left: 6px !important;
    margin-right: 6px !important;
    position: relative !important;
    transition: background-color 0.2s ease, background 0.2s ease !important;
  }

  /* Left accent crimson strip anchor line */
  div[class*="mentioned_"]::before {
    content: "" !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    bottom: 0 !important;
    width: 4px !important;
    background-color: #990033 !important; 
    border-radius: 4px 0 0 4px !important;
    z-index: 2;
  }

  /* Deepens layout color smoothly on hover */
  main div[class*="message_"][class*="mentioned_"]:hover,
  div[class*="message_"][class*="mentioned_"]:hover,
  div[class*="mentioned_"]:hover {
    background-color: rgba(166, 0, 55, 0.32) !important;
    background: rgba(166, 0, 55, 0.32) !important;
  }

  /* Keeps font formatting intact and readable over the transparent crimson */
  div[class*="mentioned_"] span,
  div[class*="mentioned_"] h3,
  div[class*="mentioned_"] div {
    --text-normal: #4d004d !important;
    --header-primary: #66004d !important;
    --text-muted: #800060 !important;
  }

  /* ===== HARD ASSIGNMENT: DARK RED CRIMSON NOTIFICATION BADGES ===== */
  div[class*="numberBadge_"], 
  div[class*="mentionsBadge_"],
  div[class*="mentionsBadge_"] div,
  div[class*="lowerBadge_"],
  div[class*="lowerBadge_"] div,
  div[class*="badge_"],
  [class*="unreadMentionsIndicator_"] {
    background-color: #4d001a !important;  
    color: #ffffff !important;             
  }

  div[class*="unread_"] {
    background-color: #80002a !important;
  }

  /* ===== INTERFACE BUTTONS & GENERIC ACTION ROLES ===== */
  button, 
  [role="button"]:not([class*="username_"]):not([class*="headerText_"]) {
    background-color: #ff66b2 !important;
    color: white !important;
    border-radius: 8px !important;
  }
  button:hover, 
  [role="button"]:not([class*="username_"]):not([class*="headerText_"]):hover {
    background-color: #ff3385 !important;
    color: white !important;
  }

  /* ===== ACCURATE TARGETING FOR ACTUAL @MENTION BADGES ONLY ===== */
  span[class*="mention_"],
  div[class*="messageContent_"] [class*="mention"] {
    background-color: #ff66b2 !important;
    color: white !important;
    border-radius: 6px !important;
    padding: 0 4px !important;
    display: inline-block !important;
  }
  span[class*="mention_"]:hover,
  div[class*="messageContent_"] [class*="mention"]:hover {
    background-color: #ff3385 !important;
  }

  /* Force standard plain styles back onto chat user headers so they are un-bubbled */
  [class*="username_"],
  [class*="headerText_"] {
    background: transparent !important;
    background-color: transparent !important;
    border-radius: 0 !important;
    padding: 0 !important;
  }

  /* ===== GLOBAL SCROLLBARS ===== */
  ::-webkit-scrollbar {
    width: 8px !important;
    height: 8px !important;
  }
  ::-webkit-scrollbar-thumb {
    background-color: #ff99cc !important;
    border-radius: 4px !important;
  }
  ::-webkit-scrollbar-track {
    background-color: #ffe6f0 !important;
  }
}
